fixtures.policyText:
@id("never-matches")
permit(principal, action == Kontext::Action::"ToolUse", resource == Kontext::Tool::"Write");
@id("catalogued-tools")
permit(principal, action == Kontext::Action::"ToolUse", resource == Kontext::Tool::"github-mcp/get_issue");

@id("ask-bash")
@ask("prompt")
@description("ask before Bash runs")
permit(principal, action == Kontext::Action::"ToolUse", resource == Kontext::Tool::"Bash");

@id("allow-tools")
permit(principal, action == Kontext::Action::"ToolUse", resource);
@id("forbid-rm")
forbid(principal, action == Kontext::Action::"ToolUse", resource == Kontext::Tool::"Bash") when { !(context has command) || (context has command && context.command == "rm -rf /") };

@id("same")
permit(principal, action == Kontext::Action::"ToolUse", resource);
@id("same")
forbid(principal, action == Kontext::Action::"ToolUse", resource);
